                                                                                                                                                                                                                
  CREATE TABLE "JW_APP"                                                                                                                                                                          
   (	"JW_APP_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 2365 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"TENANT_ID" NUMBER(20,0) DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                            
	"CREATED_BY" NVARCHAR2(256),                                                                                                                                                                                   
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                          
	"UPDATED_BY" NVARCHAR2(256),                                                                                                                                                                                   
	"UPDATE_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                            
	"APP_TYPE" VARCHAR2(64) NOT NULL ENABLE,                                                                                                                                                                       
	"AGENT_ID" VARCHAR2(255),                                                                                                                                                                                      
	"APP_NAME" VARCHAR2(255) NOT NULL ENABLE,                                                                                                                                                                      
	"APP_DESC" VARCHAR2(1024),                                                                                                                                                                                     
	"APP_ICON" VARCHAR2(1024),                                                                                                                                                                                     
	"PC_URL" VARCHAR2(1024),                                                                                                                                                                                       
	"MP_URL" VARCHAR2(1024),                                                                                                                                                                                       
	"APP_STATUS" VARCHAR2(255),                                                                                                                                                                                    
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                              
	"IS_ENABLE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                             
	"SCOPE_TYPE" VARCHAR2(15) DEFAULT 'ALL' NOT NULL ENABLE,                                                                                                                                                       
	"LOGIN_TYPE" NVARCHAR2(30) DEFAULT 'DEFAULT' NOT NULL ENABLE,                                                                                                                                                  
	"APP_OPEN_TYPE" NVARCHAR2(30) DEFAULT 'DEFAULT' NOT NULL ENABLE,                                                                                                                                               
	"DEVICE" VARCHAR2(10) DEFAULT 'ALL' NOT NULL ENABLE,                                                                                                                                                           
	"IS_BLACKLIST" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                          
	"NAME_PINYIN" VARCHAR2(2000),                                                                                                                                                                                  
	"JING_JIE_CODE" VARCHAR2(10) DEFAULT 'jjCode',                                                                                                                                                                 
	 PRIMARY KEY ("JW_APP_ID")                                                                                                                                                                                     
  USING INDEX  ENABLE                                                                                                                                                                                           
   ) ;                                                                                                                                                                                                          

